39	/// Parse a JSON object string into a serde_json Map, preserving the exact
40	/// spelling of numbers that cannot be round-tripped through f64 without loss.
41	/// Numbers that survive f64 conversion unchanged are kept as `Value::Number`;
42	/// numbers that would be corrupted (e.g. integers with >15 significant digits)
43	/// are kept as `Value::String` so the original value is available to templates.
44	/// Returns `None` when the top-level JSON value is not an object.
45	fn parse_args_object(
46	    s: &str,
47	) -> anyhow::Result<Option<serde_json::Map<String, serde_json::Value>>> {
48	    // First pass: parse the top-level value to check it is an object.
49	    let top: serde_json::Value = serde_json::from_str(s)?;
50	    let top_obj = match top {
51	        serde_json::Value::Object(m) => m,
52	        _ => return Ok(None),
53	    };
54	
55	    // Second pass: re-parse each entry's value via its RawValue to detect
56	    // numbers that serde_json would corrupt through f64.
57	    // We use a raw string-to-rawvalue helper to get the exact bytes.
58	    let mut out = serde_json::Map::with_capacity(top_obj.len());
59	    for (k, cooked) in top_obj {
60	        // For non-numbers, use the already-parsed value directly.
61	        if !cooked.is_number() {
62	            out.insert(k, cooked);
63	            continue;
64	        }
65	        // For numbers: find the raw token in the source string so we can
66	        // verify that serde_json's f64 representation matches the original.
67	        // We do this by re-serializing the cooked number and comparing.
68	        let cooked_str = cooked.to_string();
69	        if let Some(raw_token) = extract_value_token(s, &k) {
70	            let raw_trimmed = raw_token.trim();
71	            if raw_trimmed != cooked_str.as_str() {
72	                // Precision was lost (e.g. 30-digit integer → 1.23e+29).
73	                // Keep the original spelling as a string.
74	                out.insert(k, serde_json::Value::String(raw_trimmed.to_string()));
75	                continue;
76	            }
77	        }
78	        out.insert(k, cooked);
79	    }
80	    Ok(Some(out))
81	}
