83	/// Extract the raw JSON token for `key` from a JSON object string `s`.
84	/// Returns `None` when the key is not found or parsing fails.
85	fn extract_value_token<'a>(s: &'a str, key: &str) -> Option<&'a str> {
86	    // Build the escaped key as it appears in JSON.
87	    let key_json = serde_json::to_string(key).ok()?;
88	    // Find `"key":` in the source.
89	    let needle = format!("{}:", key_json);
90	    let start = s.find(needle.as_str())?;
91	    let after_colon = s[start + needle.len()..].trim_start();
92	    // Measure the extent of the JSON token.
93	    let end = token_end(after_colon)?;
94	    let source_offset = s.len() - s[start + needle.len()..].len()
95	        + (after_colon.as_ptr() as usize - s[start + needle.len()..].as_ptr() as usize);
96	    Some(&s[source_offset..source_offset + end])
97	}
98	
99	/// Return the byte length of the first JSON token in `s`.
100	fn token_end(s: &str) -> Option<usize> {
101	    let s = s.trim_start();
102	    let first = s.chars().next()?;
103	    match first {
104	        '"' => {
105	            let mut i = 1;
106	            let b = s.as_bytes();
107	            while i < b.len() {
108	                if b[i] == b'\\' {
109	                    i += 2;
110	                } else if b[i] == b'"' {
111	                    return Some(i + 1);
112	                } else {
113	                    i += 1;
114	                }
115	            }
116	            None
117	        }
118	        '{' | '[' => {
119	            // Skip balanced braces/brackets — good enough for flat objects.
120	            let (open, close) = if first == '{' {
121	                (b'{', b'}')
122	            } else {
123	                (b'[', b']')
124	            };
125	            let mut depth = 0i32;
126	            let mut in_str = false;
127	            let mut escape = false;
128	            for (i, &b) in s.as_bytes().iter().enumerate() {
129	                if escape {
130	                    escape = false;
131	                    continue;
132	                }
133	                if in_str {
134	                    if b == b'\\' {
135	                        escape = true;
136	                    } else if b == b'"' {
137	                        in_str = false;
138	                    }
139	                } else {
140	                    match b {
141	                        b'"' => in_str = true,
142	                        b if b == open => depth += 1,
143	                        b if b == close => {
144	                            depth -= 1;
145	                            if depth == 0 {
146	                                return Some(i + 1);
147	                            }
148	                        }
149	                        _ => {}
150	                    }
151	                }
152	            }
153	            None
154	        }
155	        _ => {
156	            // Number, bool, null — ends at first delimiter.
157	            let end = s
158	                .find(|c: char| c == ',' || c == '}' || c == ']' || c.is_whitespace())
159	                .unwrap_or(s.len());
160	            if end == 0 { None } else { Some(end) }
161	        }
162	    }
163	}
