165	/// Parse `tool_calls[*].function.arguments` from JSON string to object before
166	/// handing messages to MiniJinja. Some chat templates (e.g. GLM-5.2) call
167	/// `.items()` on arguments and require a dict; the OpenAI wire format carries
168	/// arguments as a JSON string. This matches TRT-LLM's chat_utils.py behaviour.
169	///
170	/// Large integer values in arguments are preserved exactly because `dynamo-llm`
171	/// enables the `serde_json/arbitrary_precision` feature.
172	///
173	/// Returns an error if any tool_call's arguments string contains invalid JSON,
174	/// so callers can surface a 400-style error instead of fabricating empty args.
175	pub(crate) fn normalize_tool_call_arguments(
176	    messages_json: &mut serde_json::Value,
177	) -> anyhow::Result<()> {
178	    let Some(messages) = messages_json.as_array_mut() else {
179	        return Ok(());
180	    };
181	    for message in messages {
182	        let Some(tool_calls) = message
183	            .get_mut("tool_calls")
184	            .and_then(serde_json::Value::as_array_mut)
185	        else {
186	            continue;
187	        };
188	        for tc in tool_calls.iter_mut() {
189	            let Some(args_str) = tc.pointer("/function/arguments").and_then(|v| v.as_str()) else {
190	                continue;
191	            };
192	            // Empty string is a valid no-argument call; normalise to {}.
193	            if args_str.is_empty() {
194	                if let Some(obj) = tc
195	                    .get_mut("function")
196	                    .and_then(serde_json::Value::as_object_mut)
197	                {
198	                    obj.insert(
199	                        "arguments".to_string(),
200	                        serde_json::Value::Object(serde_json::Map::new()),
201	                    );
202	                }
203	                continue;
204	            }
205	            let value = match parse_args_object(args_str) {
206	                Ok(Some(map)) => serde_json::Value::Object(map),
207	                Ok(None) => {
208	                    // Scalar or array — GLM's .items() would panic at render time.
209	                    tracing::warn!(
210	                        args_len = args_str.len(),
211	                        "tool_call arguments parsed to a non-object; \
212	                         substituting {{}} for template safety"
213	                    );
214	                    serde_json::Value::Object(serde_json::Map::new())
215	                }
216	                Err(e) => {
217	                    anyhow::bail!(
218	                        "tool_call arguments are not valid JSON (len={}): {e}",
219	                        args_str.len()
220	                    );
221	                }
222	            };
223	            if let Some(obj) = tc
224	                .get_mut("function")
225	                .and_then(serde_json::Value::as_object_mut)
226	            {
227	                obj.insert("arguments".to_string(), value);
228	            }
229	        }
230	    }
231	    Ok(())
232	}
