373	/// Build a [`PromptFormatter`] from a [`ModelDeploymentCard`].
374	///
375	/// Model families whose HF repos ship no Jinja `chat_template` get a native
376	/// Rust formatter; everything else loads the
377	/// HF `tokenizer_config.json` template (and any separate chat-template file)
378	/// and builds via [`PromptFormatter::from_parts`].
379	pub fn prompt_formatter_from_mdc(mdc: &ModelDeploymentCard) -> Result<PromptFormatter> {
380	    // Prefer the authoritative `model_type` from config.json — it's set by the
381	    // model author and survives any `--served-model-name` rename. An empty
382	    // `model_type` carries no signal — normalize to `None` so the display-name
383	    // fallback still runs.
384	    let model_type_lower = mdc
385	        .model_info
386	        .as_ref()
387	        .and_then(|info| info.get_model_info().ok())
388	        .map(|info| info.model_type().to_lowercase())
389	        .filter(|s| !s.is_empty());
390	    let display_name_lower = mdc.display_name.to_lowercase();
391	
392	    if let Some(formatter) = kimi_k3_formatter_for(
393	        &model_type_lower,
394	        &display_name_lower,
395	        mdc.runtime_config.exclude_tools_when_tool_choice_none,
396	    ) {
397	        return Ok(formatter);
398	    }
399	
400	    if let Some(formatter) = deepseek_formatter_for(&model_type_lower, &display_name_lower) {
401	        return Ok(formatter);
402	    }
403	
404	    match mdc
405	        .prompt_formatter
406	        .as_ref()
407	        .ok_or(anyhow::anyhow!("MDC does not contain a prompt formatter"))?
408	    {
409	        PromptFormatterArtifact::HfTokenizerConfigJson(checked_file) => {
410	            let Some(file) = checked_file.path() else {
411	                anyhow::bail!(
412	                    "HfTokenizerConfigJson for {} is a URL, cannot load",
413	                    mdc.display_name
414	                );
415	            };
416	            let contents = std::fs::read_to_string(file).with_context(|| {
417	                format!(
418	                    "prompt_formatter_from_mdc fs:read_to_string '{}'",
419	                    file.display()
420	                )
421	            })?;
422	            let mut config: ChatTemplate = serde_json::from_str(&contents).inspect_err(|err| {
423	                crate::log_json_err(&file.display().to_string(), &contents, err)
424	            })?;
425	
426	            // Some HF models (e.g. Llama-4-Maverick) store the chat template in a
427	            // separate file, or it may be a custom template provided via CLI flag.
428	            match mdc.chat_template_file.as_ref() {
429	                Some(PromptFormatterArtifact::HfChatTemplateJinja {
430	                    file: checked_file, ..
431	                }) => {
432	                    let Some(path) = checked_file.path() else {
433	                        anyhow::bail!(
434	                            "HfChatTemplateJinja for {} is a URL, cannot load",
435	                            mdc.display_name
436	                        );
437	                    };
438	                    let chat_template = std::fs::read_to_string(path)
439	                        .with_context(|| format!("fs:read_to_string '{}'", path.display()))?;
440	                    config.chat_template = Some(ChatTemplateValue(either::Left(chat_template)));
441	                }
442	                Some(PromptFormatterArtifact::HfChatTemplateJson {
443	                    file: checked_file, ..
444	                }) => {
445	                    let Some(path) = checked_file.path() else {
446	                        anyhow::bail!(
447	                            "HfChatTemplateJson for {} is a URL, cannot load",
448	                            mdc.display_name
449	                        );
450	                    };
451	                    let raw = std::fs::read_to_string(path)
452	                        .with_context(|| format!("fs:read_to_string '{}'", path.display()))?;
453	                    let wrapper: serde_json::Value = serde_json::from_str(&raw)
454	                        .with_context(|| format!("Failed to parse '{}' as JSON", path.display()))?;
455	                    let field = wrapper.get("chat_template").ok_or_else(|| {
456	                        anyhow::anyhow!(
457	                            "'{}' does not contain a 'chat_template' field",
458	                            path.display()
459	                        )
460	                    })?;
461	                    let value = serde_json::from_value::<ChatTemplateValue>(field.clone())
462	                        .with_context(|| {
463	                            format!(
464	                                "Failed to deserialize 'chat_template' in '{}'",
465	                                path.display()
466	                            )
467	                        })?;
468	                    config.chat_template = Some(value);
469	                }
470	                _ => {}
471	            }
472	            PromptFormatter::from_parts(
473	                config,
474	                mdc.prompt_context
475	                    .clone()
476	                    .map_or(ContextMixins::default(), |x| ContextMixins::new(&x)),
477	                mdc.runtime_config.exclude_tools_when_tool_choice_none,
478	            )
479	        }
480	        PromptFormatterArtifact::HfChatTemplateJinja { .. }
481	        | PromptFormatterArtifact::HfChatTemplateJson { .. } => Err(anyhow::anyhow!(
482	            "prompt_formatter should not have type HfChatTemplate*"
483	        )),
484	    }
485	}
