487	const CONTINUE_FINAL_MESSAGE_NOT_FOUND: &str =
488	    "Unable to continue the final message because it was not found in the rendered chat template.";
489	
490	/// HuggingFace `render_jinja_template` marker. Appended to last-message content
491	/// before render so truncation uniquely identifies the final turn even when the
492	/// template rewrites or repeats earlier text.
493	pub(crate) const CONTINUE_FINAL_MESSAGE_TAG: &str = "CONTINUE_FINAL_MESSAGE_TAG ";
494	
495	/// Append [`CONTINUE_FINAL_MESSAGE_TAG`] to the last message's text content.
496	/// Array content uses the last non-empty `text` part, matching Transformers.
497	pub(crate) fn append_continue_final_message_tag(messages: &mut serde_json::Value) -> Result<()> {
498	    let Some(last) = messages.as_array_mut().and_then(|arr| arr.last_mut()) else {
499	        anyhow::bail!(CONTINUE_FINAL_MESSAGE_NOT_FOUND);
500	    };
501	    match last.get_mut("content") {
502	        Some(serde_json::Value::String(text)) if !text.is_empty() => {
503	            text.push_str(CONTINUE_FINAL_MESSAGE_TAG);
504	            Ok(())
505	        }
506	        Some(serde_json::Value::Array(parts)) => {
507	            for part in parts.iter_mut().rev() {
508	                if let Some(serde_json::Value::String(text)) = part.get_mut("text") {
509	                    if text.is_empty() {
510	                        continue;
511	                    }
512	                    text.push_str(CONTINUE_FINAL_MESSAGE_TAG);
513	                    return Ok(());
514	                }
515	            }
516	            anyhow::bail!(CONTINUE_FINAL_MESSAGE_NOT_FOUND);
517	        }
518	        _ => anyhow::bail!(CONTINUE_FINAL_MESSAGE_NOT_FOUND),
519	    }
520	}
