522	/// HuggingFace `apply_chat_template(continue_final_message=True)`: after render,
523	/// drop the marker and any tokens after it so the prompt ends at the last
524	/// message text.
525	///
526	/// The renderer must have seen [`CONTINUE_FINAL_MESSAGE_TAG`] in the last
527	/// message. Searching for the raw last-message string cannot prove the match
528	/// belongs to the final turn (a template may rewrite or repeat earlier copies).
529	///
530	/// When the renderer returned segment boundaries (Kimi K3 XTML), keep them so
531	/// tokenization still uses `encode_segments` instead of flattening to plain text.
532	/// Missing marker, empty content, or a template that dropped the marker is an
533	/// invalid request rather than silently returning the closed prompt.
534	pub(crate) fn apply_continue_final_message(prompt: RenderedPrompt) -> Result<RenderedPrompt> {
535	    let rendered = prompt.as_str();
536	    let tag = CONTINUE_FINAL_MESSAGE_TAG;
537	    let tag_name = tag.trim_end();
538	    let Some(tag_loc) = rendered.rfind(tag_name) else {
539	        anyhow::bail!(CONTINUE_FINAL_MESSAGE_NOT_FOUND);
540	    };
541	    // Transformers: if the full tag (including trailing space) survived, cut
542	    // at the tag. If the template trimmed that space, also rstrip the prefix.
543	    let end = if rendered[tag_loc..].starts_with(tag) {
544	        tag_loc
545	    } else {
546	        rendered[..tag_loc].trim_end().len()
547	    };
548	    Ok(truncate_rendered_prompt(prompt, end))
549	}
