551	/// Truncate `prompt` to the first `end` bytes of `as_str()`, preserving
552	/// `RenderedSegment` trust boundaries when they are present.
553	fn truncate_rendered_prompt(prompt: RenderedPrompt, end: usize) -> RenderedPrompt {
554	    let Some(segments) = prompt.segments() else {
555	        return RenderedPrompt::text(prompt.as_str()[..end].to_string());
556	    };
557	    let mut out = Vec::new();
558	    let mut offset = 0usize;
559	    for seg in segments {
560	        let next = offset + seg.text.len();
561	        if next <= end {
562	            if !seg.text.is_empty() {
563	                out.push(seg.clone());
564	            }
565	            offset = next;
566	            if offset == end {
567	                break;
568	            }
569	            continue;
570	        }
571	        if offset < end {
572	            let keep = end - offset;
573	            if keep > 0 && keep <= seg.text.len() && seg.text.is_char_boundary(keep) {
574	                out.push(RenderedSegment {
575	                    text: seg.text[..keep].to_string(),
576	                    allow_special: seg.allow_special,
577	                });
578	            }
579	        }
580	        break;
581	    }
582	    if out.is_empty() {
583	        RenderedPrompt::text(String::new())
584	    } else {
585	        RenderedPrompt::segmented(out)
586	    }
